sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* Breadcrumbs */
.breadcrumbs {
  display: flex;
  flex-direction: row;
  align-items: center;
  font-family: "BancoDoBrasil Textos";
  color: $fazai-color-link-blue-default;
  font-weight: 400;
  height: 25px;
  gap: 8px;
  margin: 48px 0px;
}

.breadcrumbs a {
  color: $fazai-color-link-blue-default;
}


.breadcrumbs__back {
  font-size: 16px;
  display: flex;
  flex-direction: row;
  gap: 8px;
  align-items: center;
}

.breadcrumbs__divider {
  border-left: 1px;
  border-right: 0px;
  border-style: solid;
  border-color: #E5E7EB;
  margin: 0 5px;
  height: 25px;
}

.breadcrumbs__pages {
	font-size: 18px;
}

.breadcrumbs__pages a + a::before {
  content: " / "; /* The text you want to insert */
  color: $fazai-color-text-default;
  font-weight: 400;
  font-size: 18px;
  margin: 0 5px;
}

.breadcrumbs__last {
  color: $fazai-color-text-default !important;
  font-weight: 700;
  font-size: 22px;
  line-height: 35.2px;
  margin: 0px;
  pointer-events: none; /* Disables all pointer events */
  cursor: default;       /* Sets cursor to default instead of a pointer */
}

sp_widget.script:
function getPageTitle(pageID) {
    var page = new GlideRecord('sp_page');
    if (page.get('id', pageID))
        return page.getDisplayValue('title');

    return "Página";
}

function getParentPage(pageId, pages = [], verifiedPages = []) {
	// Adicionar regra para evitar recursão infinita
	if (verifiedPages.indexOf(pageId.toString()) > -1)
		return pages;

    pages.unshift({
		id: pageId,
		title: getPageTitle(pageId),
		url: '?id=' + pageId
	}); // Adicionar no começo do array

    var page = new GlideRecord('x_1083828_servic_0_breadcrumbs');
    page.addQuery('pagina.id', pageId);
    page.query();

    while (page.next()) {
		if (page.getValue('parametros_caracteristicos') ) {
			const paramsFilter = JSON.parse(page.getValue('parametros_caracteristicos'));

			// Se a página atual é final do breadcrumbs, validar parâmetros
			if (pageId == $sp.getParameter('id')) {
				const isValid = Object.keys(paramsFilter).every(param => 
					$sp.getParameter(param) == paramsFilter[param]
				);

				// Se os parâmetros característicos da hierarquia não foram antendidos, pula iteração para próxima possível hierarquia da página
				if (!isValid)
					continue;
			}

			// Adiciona parâmetros à URL
			for (const param in paramsFilter) {
				pages[0].url += '&' + param + '=' + paramsFilter[param];
			}
		}

		verifiedPages.push(pageId);

        if (page.getValue('pagina_pai'))
            return getParentPage(page.pagina_pai.pagina.id.toString(), pages, verifiedPages);
    }
    return pages;
}


(function() {
    /* populate the 'data' object */
    /* e.g., data.table = $sp.getValue('table'); */

	data.urlSuffix = $sp.getValue('url_suffix');
	const portalRecord = $sp.getPortalRecord();

	data.homepageTitle = portalRecord.homepage.title.getDisplayValue();

    var currentPage = $sp.getParameter('id');

    data.parentPages = getParentPage(currentPage);
	data.backButtonHref = ''; // Por padrão redirecionar para página inicial do portal

	if (data.parentPages.length > 1) { // Se houver página pai, redirecionar para ela
		data.backButtonHref = '?id=' + data.parentPages[data.parentPages.length - 2].id;
	}

})();
